/* Счётчик цифр при появлении в кадре. Итог всегда в разметке, бегущий слой лежит поверх в той же ячейке grid */
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:32px 24px;margin:0;padding:0;list-style:none}
.stat__num{display:inline-grid;font-size:clamp(40px,6vw,64px);font-weight:600;line-height:1;letter-spacing:-0.02em;font-variant-numeric:tabular-nums lining-nums;white-space:nowrap}
.stat__num>span{grid-area:1/1}
.stat__live{text-align:end}
.stat[data-counting] .stat__final{opacity:0}
.stat__label{display:block;margin-top:14px;font-size:15px;line-height:1.4;color:var(--text-muted,inherit)}
/* Необязательная полоса-акцент: растёт вместе со счётом. Не нужна — удалите все правила с ::before */
.stat__label::before{content:"";display:block;width:48px;height:2px;margin-bottom:12px;background:var(--cu-bar,currentColor);transform-origin:0 50%}
/* Состояния ставит JS: wait — ждёт появления в кадре (прячется мгновенно, переход висит только на run), run — проявляется и считает */
[data-cu="wait"]{opacity:0;transform:translateY(12px)}
[data-cu="run"]{transition:opacity 480ms cubic-bezier(.2,0,0,1) var(--cu-delay,0ms),transform 480ms cubic-bezier(.2,0,0,1) var(--cu-delay,0ms)}
[data-cu="wait"] .stat__label::before{transform:scaleX(0)}
[data-cu="run"] .stat__label::before{transition:transform var(--cu-dur,1200ms) cubic-bezier(.33,1,.68,1) var(--cu-delay,0ms);}
/* Уменьшение движения (три уровня): сдвиг и рост полосы убраны, счёта нет (итог сразу, это делает JS), остаётся проявление 150 мс */
@media (prefers-reduced-motion: reduce){
  [data-cu]{transform:none!important}
  [data-cu="run"]{transition:opacity 150ms linear!important}
  [data-cu] .stat__label::before{transform:none!important;transition:none!important;}
}
@media print{
  [data-cu]{opacity:1!important;transform:none!important}
  .stat[data-counting] .stat__final{opacity:1}
  .stat__live{display:none}
}

