(() => {
  const items = document.querySelectorAll('[data-count-to]');
  if (!items.length || !('IntersectionObserver' in window)) return; // без IO остаются итоговые числа
  const mq = matchMedia('(prefers-reduced-motion: reduce)');
  const ease = t => 1 - Math.pow(1 - t, 3); // ease-out cubic = cubic-bezier(.33,1,.68,1)
  const fmts = {}, view = (el, v) => {
    const d = +el.dataset.countDecimals || 0;
    const f = fmts[d] || (fmts[d] = new Intl.NumberFormat('ru-RU', { minimumFractionDigits: d, maximumFractionDigits: d }));
    return (el.dataset.countPrefix || '') + f.format(v) + (el.dataset.countSuffix || '');
  };
  const run = (el, delay) => {
    const to = parseFloat(el.dataset.countTo), from = parseFloat(el.dataset.countFrom) || 0;
    const dur = parseFloat(el.dataset.countDuration) || 1200, live = el.querySelector('.stat__live');
    el.style.setProperty('--cu-delay', delay + 'ms'); el.style.setProperty('--cu-dur', dur + 'ms');
    el.dataset.cu = 'run';
    if (mq.matches || !live) return; // уменьшение движения: итог сразу, без счёта
    el.setAttribute('data-counting', '');
    const t0 = performance.now() + delay;
    const tick = now => {
      const p = Math.min(Math.max((now - t0) / dur, 0), 1);
      live.textContent = view(el, from + (to - from) * ease(p));
      if (p < 1) return requestAnimationFrame(tick);
      el.removeAttribute('data-counting'); live.textContent = '';
    };
    tick(performance.now());
  };
  let left = 0; // сколько счётчиков ещё ждут появления в кадре
  const io = new IntersectionObserver(entries => {
    entries.filter(e => e.isIntersecting).forEach((e, i) => { io.unobserve(e.target); left--; run(e.target, Math.min(i * 90, 360)); });
    if (!left) io.disconnect(); // все отработали — наблюдатель больше не нужен
  }, { threshold: 0.5, rootMargin: '0px 0px -8% 0px' });
  items.forEach(el => {
    const to = parseFloat(el.dataset.countTo), r = el.getBoundingClientRect();
    if (!isFinite(to) || (r.top < innerHeight && r.bottom > 0)) return; // уже в кадре при загрузке — показываем итог без счёта
    const fin = el.querySelector('.stat__final'); if (fin) fin.textContent = view(el, to); // итог в том же формате, что и бегущие цифры
    el.dataset.cu = 'wait';
    io.observe(el); left++;
  });
})();

gsap_alt:
// Установка из npm, без CDN: npm i gsap (GSAP распространяется по своей бесплатной Standard License, это не MIT).
// Разметка и CSS те же; атрибуты data-cu не нужны (полоса стоит статично), правило [data-counting] используется.
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
const inView = el => { const r = el.getBoundingClientRect(); return r.top < innerHeight && r.bottom > 0; };
const mm = gsap.matchMedia();
mm.add('(prefers-reduced-motion: no-preference)', ctx => { // при уменьшении движения ничего не создаём — видны итоги
  const items = gsap.utils.toArray('.stat[data-count-to]').filter(el =>
    isFinite(parseFloat(el.dataset.countTo)) && el.querySelector('.stat__live') && !inView(el)); // первый экран не трогаем
  if (!items.length) return;
  const play = (el, delay) => {
    const live = el.querySelector('.stat__live'), d = +el.dataset.countDecimals || 0;
    const f = new Intl.NumberFormat('ru-RU', { minimumFractionDigits: d, maximumFractionDigits: d });
    const text = v => (el.dataset.countPrefix || '') + f.format(v) + (el.dataset.countSuffix || '');
    const n = { v: parseFloat(el.dataset.countFrom) || 0 }, to = parseFloat(el.dataset.countTo);
    el.querySelector('.stat__final').textContent = text(to); // итог в том же формате, что и бегущие цифры
    gsap.timeline({ delay })
      .to(el, { autoAlpha: 1, y: 0, duration: 0.48, ease: 'power2.out' })
      .to(n, { v: to, duration: 1.2, ease: 'power2.out', // power2.out = ease-out cubic
        onStart: () => el.setAttribute('data-counting', ''),
        onUpdate: () => { live.textContent = text(n.v); },
        onComplete: () => { el.removeAttribute('data-counting'); live.textContent = ''; } }, 0);
  };
  gsap.set(items, { autoAlpha: 0, y: 12 });
  ScrollTrigger.batch(items, { start: 'top 85%', once: true, // очередь 90 мс, вся не длиннее 360 мс
    onEnter: batch => ctx.add(() => batch.forEach((el, i) => play(el, Math.min(i * 0.09, 0.36)))) }); // ctx.add — чтобы откат увидел и эти анимации
  return () => items.forEach(el => { el.removeAttribute('data-counting'); el.querySelector('.stat__live').textContent = ''; }); // настройку включили на лету — сразу итоги
});
